    // Collaborator cannot push anymore
    response = await app.request(`/repos/alice/test-repo/refs/heads/main`, { method: "PUT", headers: { authorization: `Bearer ${token}` }, body: JSON.stringify({ sha: "0000000000000000000000000000000000000001" }) });
